package com.nyayaconnect.ai;
import java.util.*;
public final class TriageClassifier {
 private TriageClassifier(){}
 public static LegalTriage classify(String raw){String q=raw==null?"":raw.toLowerCase(Locale.ROOT);if(q.isBlank())throw new IllegalArgumentException("Query is required.");
  if(has(q,"cheque","bounce","dishonour","138"))return result("Cheque Bounce & Debt Recovery","Commercial & Banking Law","High", "MEDIUM", List.of("Negotiable Instruments Act, 1881"),List.of("Cheque and return memo","Underlying agreement/invoice","Payment and notice records"),List.of("Preserve the original cheque and bank memo.","Have an advocate verify statutory notice timelines.","Prepare the underlying debt evidence."),List.of("Banking & Debt Recovery Advocate","Commercial Litigation Lawyer"));
  if(has(q,"cyber","fraud","scam","otp","upi","hack","phishing"))return result("Cyber Crime & Financial Fraud","Cyber Law & Criminal Law","Critical","MEDIUM",List.of("Information Technology Act, 2000","Applicable criminal law"),List.of("Bank statement/UTR","Screenshots and messages","Complaint acknowledgement"),List.of("Contact the bank immediately.","Preserve digital evidence without alteration.","Consult a cyber-crime advocate and use official reporting channels."),List.of("Cyber Crime Advocate","Financial Fraud Lawyer"));
  if(has(q,"landlord","tenant","rent","deposit","eviction","kiraya","makan"))return result("Tenancy & Rental Dispute","Property & Real Estate Law","Medium","LOW",List.of("Transfer of Property Act, 1882","Applicable state tenancy/rent law"),List.of("Lease/rent agreement","Deposit payment proof","Notice and communication history"),List.of("Collect the agreement and payment trail.","Check the applicable state tenancy law.","Have an advocate review notice and limitation issues."),List.of("Property Lawyer","Civil Litigation Lawyer"));
  if(has(q,"divorce","custody","maintenance","domestic","matrimonial","talaq"))return result("Matrimonial & Family Dispute","Family Law","Medium","LOW",List.of("Applicable personal/family law","Protection of Women from Domestic Violence Act, 2005 where applicable"),List.of("Marriage proof","Relevant financial records","Relevant communications/orders"),List.of("Preserve documents and communications.","Consider mediation where appropriate.","Consult a family-law advocate for jurisdiction-specific advice."),List.of("Family Court Lawyer","Matrimonial Advocate"));
  return result("Civil / Consumer Grievance","Civil & Consumer Law","Low","LOW",List.of("Consumer Protection Act, 2019 where applicable","Indian Contract Act, 1872 where applicable"),List.of("Contract/invoice","Payment proof","Complaint correspondence"),List.of("Organize the transaction record.","Check the applicable forum and limitation.","Discuss the facts with a verified advocate."),List.of("Civil Litigation Lawyer","Consumer Rights Advocate"));
 }
 private static boolean has(String q,String...xs){for(String x:xs)if(q.contains(x))return true;return false;}
 private static LegalTriage result(String c,String p,String u,String cl,List<String>a,List<String>d,List<String>n,List<String>s){return new LegalTriage(c,p,u,cl,"Pre-consultation issue triage only. The result is not legal advice or a determination of rights.",a,d,"The platform has not verified a source-backed legal conclusion for this triage result. A lawyer should review the facts and applicable law.",n,s,List.of(),false);}
}
